          const moves = this.battlefield.filter(x => !x.phasedOut && !(e.exceptSelf && src && x.id === src.id) &&
            this._cardFitsWords(x, e.what || 'nonland permanent')).map(x => [x, takerOf(x.controller)]).filter(m => m[1] && m[1] !== m[0].controller);
