              const objs = pool.filter(t => t.kind === 'object').map(t => this.obj(t.id)).sort((a, b) => ((b.card && b.card.cmc) || 0) - ((a.card && a.card.cmc) || 0));
              pick = t0.kind === 'object' && objs.length ? { kind: 'object', id: objs[0].id } : pool[0];
