          const who = e.who === 'each' ? this._turnOrderFrom(ctx.controller).filter(p => !p.hasLost && (!e.pids || e.pids.includes(p.id))) : e.who === 'triggerPlayer' ? [triggerPlayer()].filter(p => p && !p.hasLost) : [me];
