            const rest = (this._lastExiledList || []).map(id => this.obj(id)).filter(o => o && o.zone === 'exile');
            for (const o of (e.random ? this.rng.shuffle(rest.slice()) : rest)) this.moveObject(o, 'library', { toBottom: true });
